import { Box, Button, IconButton, Stack, Tooltip, Typography } from '@mui/material'
import CalendarOutline from 'mdi-material-ui/CalendarOutline'
import ArrowCollapseVertical from 'mdi-material-ui/ArrowCollapseVertical'
import ArrowExpandVertical from 'mdi-material-ui/ArrowExpandVertical'
import Close from 'mdi-material-ui/Close'
import Play from 'mdi-material-ui/Play'
import ArrowUpwardOutlined from '@mui/icons-material/ArrowUpwardOutlined'
import CheckOutlined from '@mui/icons-material/CheckOutlined'
import StopOutlined from '@mui/icons-material/StopOutlined'
import type { ActionContext } from '../../data/action_context'
import type { ActionExecutionStatus } from '../../data/action_run_types'
import { CUSTOM_PROMPT_ACTION_ID, type ActionDefinition } from '../../data/action_types'
import type { AgentConversation } from '../../data/data_types'
import { worktreeService } from '../../services/project/worktree_service'
import { ResizablePopper } from '../resizable_popper'
import { WorktreeSelector, type WorktreeAssignment, type WorktreeAssignmentTarget } from '../worktree_selector'
import { ActionAgentPresetName } from './action_agent_preset_name'
import { ActionAgentPrompt } from './action_agent_prompt'
import { ActionAgentQuestion } from './action_agent_question'
import { ActionAgentSelectors } from './action_agent_selectors'
import { ActionConversationChat } from './action_conversation_chat'
import { ActionConversationPicker } from './action_conversation_picker'
import { ActionLogErrorDisplay } from './action_log_error_display'
import { ActionPhraseButtons } from './action_phrase_buttons'
import { statusColor } from './action_popup_defaults'
import { ActionRunHistory } from './action_run_history'
import { ActionRunStatus } from './action_run_status'
import { ActionScheduleForm } from './action_schedule_form'
import { ActionSelector } from './action_selector'
import { ActionUsageSummary } from './action_usage_summary'
import { useActionPopupController } from './use_action_popup_controller'

export const CARD_RUN_POPUP_SIZE_STORAGE_KEY = 'md2.cardRunPopupSize'
export const PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY = 'md2.projectAgentPopupSize'
const MIN_CHAT_HEIGHT = 96

interface ActionPopupContentProps {
    activeActionStatuses: Record<string, ActionExecutionStatus>
    action: ActionDefinition
    actions: ActionDefinition[]
    anchorElement: HTMLElement | null
    assignmentContext: ActionContext
    baseContext: ActionContext
    draggable?: boolean
    fullHeight: boolean
    onAddAction: () => void
    onClose: () => void
    onConversationViewed?: (conversation: AgentConversation) => void
    onSelectAction: (actionId: string) => void
    onToggleFullHeight: () => void
    open: boolean
    primaryPath: string | null
    showSaveControls: boolean
    titleId: string
    unseenResultActionIds?: string[]
}

/**
 * The message is rebuilt on every render but only reads the worktree list on the failing
 * path, so the popup never subscribes to worktree changes to keep a message it rarely shows.
 */
function worktreeValidationMessage(action: ActionDefinition, context: ActionContext) {
    const hasWorktreeAssignment = context.worktree !== undefined || !!context.worktreeError
    if (!hasWorktreeAssignment && !action.needsWorkTree) return null
    if (context.kind !== 'card' && context.kind !== 'project') {
        const reason = action.needsWorkTree ? 'when needsWorkTree is set' : 'for worktree execution'
        return `Action "${action.label}" requires card or project context ${reason}`
    }
    if (context.worktreeError) return context.worktreeError
    if (context.worktree === undefined) return `Action "${action.label}" requires a worktree assignment`
    if (!/^[1-9]\d*$/u.test(context.worktree)) return `Invalid worktree index: ${context.worktree}`

    const worktree = Number.parseInt(context.worktree, 10)
    if (!Number.isSafeInteger(worktree)) return `Invalid worktree index: ${context.worktree}`
    const record = worktreeService.getRecords()[worktree - 1]
    if (!record) return `Configured worktree ${worktree} does not exist`
    if (!record.valid) return `Configured worktree ${worktree} is invalid: ${record.error}`

    return null
}

function worktreeAssignmentTarget(context: ActionContext): WorktreeAssignmentTarget | null {
    if (context.kind === 'project') return { kind: 'project' }
    if ((context.kind === 'card' || context.kind === 'file') && context.file) return { kind: 'card', path: context.file }

    return null
}

/** Presentation and execution behavior for the internally selected popup action. */
export function ActionPopupContent(props: ActionPopupContentProps) {
    const {
        action, actions, activeActionStatuses, anchorElement, assignmentContext, baseContext, draggable, fullHeight, onAddAction, onClose,
        onSelectAction, onToggleFullHeight, open, primaryPath, showSaveControls, titleId, unseenResultActionIds = [],
    } = props
    const controller = useActionPopupController({
        action,
        context: assignmentContext,
        scheduleContext: baseContext,
        enableConversations: action.type === 'agent',
        executionValidationError: worktreeValidationMessage(action, assignmentContext),
    })
    const promptRequired = action.id === CUSTOM_PROMPT_ACTION_ID
    const sessionActive = controller.runStatus === 'queued'
        || controller.runStatus === 'running'
        || controller.runStatus === 'waitingForInput'
    const showAgentInteraction = action.type === 'agent' || controller.agentActive
    const showAgentSend = sessionActive ? controller.agentActive : action.type === 'agent'
    const showCommandRun = !sessionActive && action.type === 'command'
    const sizeStorageKey = baseContext.kind === 'project'
        ? PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY
        : CARD_RUN_POPUP_SIZE_STORAGE_KEY
    const handlePrimaryRun = showSaveControls ? controller.handleSaveAndRun : controller.handleRun
    const showUsageSummary = baseContext.kind === 'card' && !!baseContext.file
    const runDisabled = !!controller.executionDisabledMessage
        || controller.promptPreparationPending
        || controller.promptPreparationFailed
        || (promptRequired && controller.prompt.trim().length === 0)
        || (controller.agentActive && (
            !controller.interactionReady
            || controller.prompt.trim().length === 0
            || !!controller.structuredQuestion
        ))
        || (sessionActive && !controller.agentActive)
        || (showSaveControls && controller.saveDisabled)
    const parsedWorktree = assignmentContext.worktree && /^[1-9]\d*$/u.test(assignmentContext.worktree)
        ? Number.parseInt(assignmentContext.worktree, 10)
        : null
    const worktreeAssignment: WorktreeAssignment = {
        worktree: parsedWorktree,
        worktreeError: assignmentContext.worktreeError ?? null,
        worktreeValue: assignmentContext.worktree ?? null,
    }
    const assignmentTarget = baseContext.kind === 'card' || baseContext.kind === 'file' || baseContext.kind === 'project'
        ? worktreeAssignmentTarget(baseContext)
        : null

    return (
        <ResizablePopper
            anchorElement={anchorElement}
            draggable={draggable}
            fullHeight={fullHeight}
            initialSize={{ height: 450, width: 400 }}
            labelId={titleId}
            onClose={onClose}
            open={open}
            paperSx={{
                bgcolor: 'background.paper',
                border: 1,
                borderColor: 'divider',
                borderRadius: '14px',
                boxShadow: '0 24px 60px rgba(16,24,40,0.28)',
                flexDirection: 'column',
            }}
            resizeFromAllSides
            resizeLabel="Resize action popup"
            storageKey={sizeStorageKey}
        >
            <Typography
                id={titleId}
                sx={{ clip: 'rect(0 0 0 0)', clipPath: 'inset(50%)', height: 1, overflow: 'hidden', position: 'absolute', whiteSpace: 'nowrap', width: 1 }}
            >
                Run actions
            </Typography>
            <Box
                data-drag-handle={draggable ? 'true' : undefined}
                sx={{
                    borderBottom: 1, borderColor: 'divider', cursor: draggable ? 'move' : undefined,
                    display: 'flex', flexDirection: 'column', gap: 1, px: 1.5, py: 1.5,
                }}
            >
                <Box data-testid="action-popup-toolbar" sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>
                    {assignmentTarget ? (
                        <WorktreeSelector
                            assignment={worktreeAssignment}
                            assignmentTarget={assignmentTarget}
                            disabled={sessionActive}
                            primaryPath={primaryPath}
                        />
                    ) : null}
                    {action.type === 'agent' ? (
                        <ActionConversationPicker
                            conversations={controller.conversations}
                            disabled={sessionActive}
                            loading={controller.conversationHistoryLoading}
                            onChange={controller.handleConversationChange}
                            selectedPath={controller.displayedConversation?.path ?? ''}
                        />
                    ) : null}
                    <Box sx={{ flex: 1 }} />
                    <Tooltip title={fullHeight ? 'Collapse downward' : 'Expand upward'}>
                        <IconButton
                            aria-label={fullHeight ? 'Collapse downward' : 'Expand upward'}
                            onClick={onToggleFullHeight}
                            size="small"
                            sx={{ flexShrink: 0, height: 30, width: 30 }}
                        >
                            {fullHeight ? <ArrowCollapseVertical sx={{ fontSize: 18 }} /> : <ArrowExpandVertical sx={{ fontSize: 18 }} />}
                        </IconButton>
                    </Tooltip>
                    <IconButton aria-label="Close" onClick={onClose} size="small" sx={{ flexShrink: 0, height: 30, width: 30 }}>
                        <Close sx={{ fontSize: 18 }} />
                    </IconButton>
                </Box>
                <ActionSelector
                    activeActionStatuses={activeActionStatuses}
                    adding={showSaveControls}
                    actions={actions}
                    onAdd={onAddAction}
                    onSelect={onSelectAction}
                    selectedAction={action}
                    unseenResultActionIds={unseenResultActionIds}
                />
            </Box>
            <Stack spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
                {showAgentInteraction ? (
                    <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
                        {showSaveControls ? (
                            <ActionAgentPresetName
                                actionLabel={controller.actionLabel}
                                onActionLabelChange={controller.handleActionLabelChange}
                                onRunShortcut={runDisabled ? undefined : handlePrimaryRun}
                            />
                        ) : null}
                        <Box sx={{ alignItems: 'center', color: 'text.secondary', display: 'flex', flexWrap: 'wrap', fontSize: 12, gap: 0.75 }}>
                            {action.type === 'agent' ? (
                                <ActionAgentSelectors
                                    agent={controller.agent}
                                    agentAvailability={controller.agentAvailability}
                                    agentProfiles={controller.agentProfiles}
                                    disabled={sessionActive}
                                    model={controller.model}
                                    onAgentChange={controller.handleAgentChange}
                                    onModelChange={controller.handleModelChange}
                                    onThinkingLevelChange={controller.handleThinkingLevelChange}
                                    selectedAgentModels={controller.selectedAgentModels}
                                    thinkingLevel={controller.thinkingLevel}
                                />
                            ) : null}
                            <ActionLogErrorDisplay logs={controller.runLogs} />
                        </Box>
                        <Box sx={{ flex: 1, minHeight: MIN_CHAT_HEIGHT, overflowY: 'auto' }}>
                            <ActionConversationChat
                                conversation={controller.displayedConversation}
                                onConversationViewed={props.onConversationViewed}
                                status={controller.runStatus}
                            />
                        </Box>
                        <ActionAgentPrompt
                            convertMessage={controller.convertMessage}
                            disabled={false}
                            onPromptChange={controller.handlePromptChange}
                            onRunShortcut={runDisabled ? undefined : handlePrimaryRun}
                            prompt={controller.prompt}
                            promptFailed={controller.promptPreparationFailed}
                            promptLoading={controller.promptPreparationPending}
                            promptResetToken={controller.promptResetToken}
                        />
                        {controller.structuredQuestion ? (
                            <ActionAgentQuestion
                                onAnswer={controller.handleAnswerQuestion}
                                questions={controller.structuredQuestion.questions}
                            />
                        ) : null}
                    </Stack>
                ) : null}
                {controller.isFollowUp && action.phrases.length > 0 ? (
                    <ActionPhraseButtons
                        onDoubleClick={controller.handlePhraseDoubleClick}
                        onSelect={controller.handlePhraseSelect}
                        phrases={action.phrases}
                    />
                ) : null}
                {controller.scheduleOpen ? (
                    <ActionScheduleForm
                        message={controller.scheduleMessage}
                        onRegister={controller.handleScheduleAction}
                        onTimestampChange={controller.handleScheduleTimestampChange}
                        timestamp={controller.scheduleTimestamp}
                    />
                ) : null}
                {action.type !== 'agent' && controller.runStatus !== 'idle' ? (
                    <ActionRunStatus
                        color={statusColor(controller.runStatus)}
                        logs={controller.runLogs}
                        status={controller.runStatus}
                    />
                ) : null}
                {controller.executionDisabledMessage ? (
                    <Typography color="text.secondary" role="note" variant="caption">
                        {controller.executionDisabledMessage}
                    </Typography>
                ) : null}
                {controller.executionValidationError ? (
                    <Typography color="error.main" role="alert" variant="caption">
                        {controller.executionValidationError}
                    </Typography>
                ) : null}
                {action.type !== 'agent' ? (
                    <ActionRunHistory compact entries={controller.history} error={controller.historyError} />
                ) : null}
            </Stack>
            <Box sx={{ alignItems: 'center', bgcolor: 'background.default', borderTop: 1, borderColor: 'divider', display: 'flex', gap: 1, px: 2, py: 1.5 }}>
                {showUsageSummary && action.type === 'agent' && assignmentContext.cardInternalId ? (
                    <ActionUsageSummary
                        actionId={action.id}
                        cardInternalId={assignmentContext.cardInternalId}
                        conversations={controller.conversations}
                        history={controller.history}
                    />
                ) : null}
                <Box sx={{ flex: 1 }} />
                {sessionActive ? (
                    <Tooltip title="Stop">
                        <span>
                            <IconButton
                                aria-label="Stop"
                                disabled={!controller.backendAvailable}
                                onClick={controller.handleCancel}
                                size="small"
                            >
                                <StopOutlined sx={{ fontSize: 18 }} />
                            </IconButton>
                        </span>
                    </Tooltip>
                ) : null}
                {controller.manualFinishAvailable ? (
                    <Tooltip title="Finish">
                        <span>
                            <IconButton
                                aria-label="Finish"
                                disabled={!controller.backendAvailable || !controller.interactionReady}
                                onClick={controller.handleFinish}
                                size="small"
                            >
                                <CheckOutlined sx={{ fontSize: 18 }} />
                            </IconButton>
                        </span>
                    </Tooltip>
                ) : null}
                {showSaveControls ? (
                    <Button disabled={controller.saveDisabled} onClick={controller.handleConvertToAction} size="small" variant="outlined">
                        Save
                    </Button>
                ) : null}
                <Button
                    disabled={sessionActive || !controller.backendAvailable}
                    onClick={controller.handleToggleSchedule}
                    size="small"
                    startIcon={<CalendarOutline sx={{ fontSize: '14px !important' }} />}
                    sx={{
                        bgcolor: 'background.paper',
                        borderColor: 'divider',
                        color: 'text.secondary',
                        height: 34,
                        '&:hover': { borderColor: 'primary.main', color: 'primary.main' },
                    }}
                    variant="outlined"
                >
                    Schedule
                </Button>
                {showAgentSend ? (
                    <Tooltip title="Send">
                        <span>
                            <IconButton
                                aria-label="Send"
                                color="primary"
                                disabled={runDisabled}
                                onClick={handlePrimaryRun}
                                size="small"
                            >
                                <ArrowUpwardOutlined sx={{ fontSize: 18 }} />
                            </IconButton>
                        </span>
                    </Tooltip>
                ) : showCommandRun ? (
                    <Button
                        disabled={runDisabled}
                        onClick={handlePrimaryRun}
                        size="small"
                        startIcon={<Play sx={{ fontSize: '13px !important' }} />}
                        sx={{ height: 34, px: 2 }}
                        variant="contained"
                    >
                        Run
                    </Button>
                ) : null}
            </Box>
        </ResizablePopper>
    )
}

import { useEffect, useRef, useState } from 'react'
import type { ChangeEvent } from 'react'
import { actionContextIdentity } from '../../data/action_context'
import type { ActionContext } from '../../data/action_context'
import type { ActionDefinition } from '../../data/action_types'
import { hasExecutionBackend, type ActionRunHistoryEntry } from '../../data/electron_action_bridge'
import {
    defaultModelForProfile,
    findAgentProfile,
    mergeAgentProfiles,
    type ThinkingLevel,
    validateThinkingLevel,
} from '../../data/agent_profiles'
import type { ActionExecutionStatus, ActionRunResult } from '../../data/action_run_types'
import type { AgentConversation } from '../../data/data_types'
import { actionExecutionService, type LiveAgentTurn } from '../../services/actions/action_execution_service'
import { dialogService } from '../../services/dialog_service'
import { useActionExecution } from '../hooks/use_action_executions'
import { useConfigValueOrFallback } from '../hooks/use_config_value'
import { useAgentCapabilities } from '../hooks/use_agent_capabilities'
import {
    defaultCancelAction,
    defaultAnswerQuestion,
    defaultConvertPromptToAction,
    defaultLoadConversation,
    defaultLoadConversations,
    defaultLoadHistory,
    defaultPreparePrompt,
    defaultFinishAction,
    defaultRunAction,
    defaultSendMessage,
    defaultScheduleAction,
    type CancelAction,
    type AnswerQuestion,
    type ConvertPromptToAction,
    type LoadConversation,
    type LoadConversations,
    type LoadHistory,
    type FinishAction,
    type PopupRunStatus,
    type PreparePrompt,
    type RunAction,
    type SendMessage,
    type ScheduleAction,
} from './action_popup_defaults'
import { createScheduleTrigger } from './action_schedule_trigger'

const DEFAULT_CONVERT_LABEL_LENGTH = 40
type PromptPreparationStatus = 'failed' | 'loading' | 'ready'

interface ActionPopupControllerInput {
    action: ActionDefinition
    answerQuestion?: AnswerQuestion
    cancelAction?: CancelAction
    continueFrom?: string
    context: ActionContext
    convertPromptToAction?: ConvertPromptToAction
    enableConversations?: boolean
    executionValidationError?: string | null
    finishAction?: FinishAction
    initialPrompt?: string
    loadConversation?: LoadConversation
    loadConversations?: LoadConversations
    loadHistory?: LoadHistory
    preparePrompt?: PreparePrompt
    runAction?: RunAction
    sendMessage?: SendMessage
    scheduleContext?: ActionContext
    scheduleAction?: ScheduleAction
}

function belongsToContext(conversation: AgentConversation, context: ActionContext) {
    return context.kind === 'project'
        ? conversation.cardInternalId === null
        : conversation.cardInternalId === context.cardInternalId
}

function belongsToAction(conversation: AgentConversation, actionId: string, context: ActionContext) {
    return belongsToContext(conversation, context) && conversation.actionId === actionId
}

function conversationTimestamp(conversation: AgentConversation) {
    const timestamp = Date.parse(conversation.startedAt)

    return Number.isNaN(timestamp) ? 0 : timestamp
}

function conversationContextKey(actionId: string, context: ActionContext) {
    return `${actionId}\u0000${actionContextIdentity(context)}`
}

function liveAgentConversation(
    turn: LiveAgentTurn,
    actionId: string,
    context: ActionContext,
    status: ActionExecutionStatus,
    base: AgentConversation | null,
): AgentConversation {
    const assistantMessageId = `${turn.conversationId}-assistant-draft`
    const liveMessageIds = new Set(turn.messages.map(({ id }) => id))
    const priorMessages = (base?.messages ?? []).filter(({ id }) => !liveMessageIds.has(id) && id !== assistantMessageId)
    const messages = [
        ...priorMessages,
        ...turn.messages,
        ...(turn.assistantText.length > 0 ? [{
            content: turn.assistantText,
            id: assistantMessageId,
            role: 'assistant' as const,
            timestamp: turn.startedAt,
        }] : []),
    ]
    const conversationStatus = status === 'queued' || status === 'running' || status === 'waitingForInput'
        ? status === 'queued' ? 'running' : status
        : status === 'cancelled'
            ? 'cancelled'
            : status === 'failed'
                ? 'failed'
                : 'completed'

    return {
        actionId,
        cardInternalId: context.cardInternalId ?? null,
        cardPath: context.file ?? null,
        completedAt: null,
        events: base?.events ?? [],
        hasExplicitTitle: base?.hasExplicitTitle ?? true,
        id: turn.conversationId,
        messages,
        path: turn.reference,
        providerSessions: base?.providerSessions ?? [],
        startedAt: base?.startedAt ?? turn.startedAt,
        status: conversationStatus,
        title: base?.title ?? turn.title,
        ...(base?.usage ? { usage: base.usage } : {}),
    }
}

export function mergeConversationHistory(
    conversations: AgentConversation[],
    actionId: string,
    context: ActionContext,
    liveConversation: AgentConversation | null,
) {
    const byId = new Map<string, AgentConversation>()
    for (const conversation of conversations) {
        if (belongsToAction(conversation, actionId, context)) byId.set(conversation.id, conversation)
    }
    if (liveConversation && belongsToAction(liveConversation, actionId, context)) byId.set(liveConversation.id, liveConversation)

    return [...byId.values()].sort((left, right) => conversationTimestamp(right) - conversationTimestamp(left))
}

/** Own action popup state, injected services, and UI callbacks. */
export function useActionPopupController(input: ActionPopupControllerInput) {
    const { action, context } = input
    const configuredAgent = useConfigValueOrFallback('desktop.agent', '')
    const configuredAgentProfiles = useConfigValueOrFallback('desktop.agentProfiles', [])
    const configuredModel = useConfigValueOrFallback('desktop.model', '')
    const configuredThinkingLevel = useConfigValueOrFallback('desktop.thinkingLevel', 'none')
    const capabilities = useAgentCapabilities()
    const sharedExecution = useActionExecution(action.id, context)
    const convertPromptToAction = input.convertPromptToAction ?? defaultConvertPromptToAction
    const cancelAction = input.cancelAction ?? defaultCancelAction
    const answerQuestion = input.answerQuestion ?? defaultAnswerQuestion
    const finishAction = input.finishAction ?? defaultFinishAction
    const loadHistory = input.loadHistory ?? defaultLoadHistory
    const loadConversation = input.loadConversation ?? defaultLoadConversation
    const loadConversations = input.loadConversations ?? defaultLoadConversations
    const preparePrompt = input.preparePrompt ?? defaultPreparePrompt
    const runAction = input.runAction ?? defaultRunAction
    const sendMessage = input.sendMessage ?? defaultSendMessage
    const scheduleAction = input.scheduleAction ?? defaultScheduleAction
    const promptContextKey = conversationContextKey(action.id, context)
    const interactionKey = sharedExecution?.activeActionId
        ? `${sharedExecution.executionId}\u0000${sharedExecution.activeActionId}`
        : promptContextKey
    const sharedPromptDraft = actionExecutionService.getPromptDraft(action.id, context)
    const initialPrompt = sharedPromptDraft || input.initialPrompt || ''
    const promptKey = `${interactionKey}\u0000${input.continueFrom ?? ''}\u0000${input.initialPrompt ?? ''}`
    const agentProfiles = mergeAgentProfiles(configuredAgentProfiles)
    const defaultAgent = action.agent ?? configuredAgent
    const defaultAgentProfile = findAgentProfile(agentProfiles, defaultAgent)
    const defaultModel = (action.model ?? configuredModel) || (defaultAgentProfile ? defaultModelForProfile(defaultAgentProfile) : '')
    const definitionThinkingLevel = validateThinkingLevel(action.thinkingLevel ?? configuredThinkingLevel, `action "${action.label}"`)
    const [actionLabel, setActionLabel] = useState('')
    const [agentOverride, setAgentOverride] = useState<string | null>(null)
    const [convertMessage, setConvertMessage] = useState<string | null>(null)
    const [conversationHistoryState, setConversationHistoryState] = useState<{ conversations: AgentConversation[], key: string }>({ conversations: [], key: '' })
    const [promptState, setPromptState] = useState<{ key: string, status: PromptPreparationStatus, value: string }>({
        key: promptKey,
        status: action.type === 'agent' && !input.continueFrom ? 'loading' : 'ready',
        value: initialPrompt,
    })
    // Bumped whenever the prompt is replaced externally (prepared, phrase, cleared) but
    // never while typing, so an uncontrolled markdown editor can reseed only on real resets.
    const [promptResetToken, setPromptResetToken] = useState(0)
    const [localExecutionId, setLocalExecutionId] = useState<string | null>(null)
    const [history, setHistory] = useState<ActionRunHistoryEntry[]>([])
    const [historyError, setHistoryError] = useState<string | null>(null)
    const [modelOverride, setModelOverride] = useState<string | null>(null)
    const [localRunResult, setLocalRunResult] = useState<ActionRunResult | null>(null)
    const [localRunStatus, setLocalRunStatus] = useState<PopupRunStatus>('idle')
    const [scheduleMessage, setScheduleMessage] = useState<string | null>(null)
    const [scheduleOpen, setScheduleOpen] = useState(false)
    const [scheduleTimestamp, setScheduleTimestamp] = useState('')
    const [liveActionKey, setLiveActionKey] = useState<string | null>(null)
    const [selectedConversationState, setSelectedConversationState] = useState<{ conversation: AgentConversation | null, key: string }>({ conversation: null, key: '' })
    const [thinkingLevelOverride, setThinkingLevelOverride] = useState<{ actionId: string, value: ThinkingLevel } | null>(null)
    const actionRef = useRef(action)
    const contextRef = useRef(context)
    const selectionRequestRef = useRef(0)
    const promptEditRevisionRef = useRef(0)
    const promptRequestRef = useRef(0)
    const agent = agentOverride ?? defaultAgent
    const model = modelOverride ?? defaultModel
    const selectedAgentProfile = findAgentProfile(agentProfiles, agent)
    const selectedAgentModels = selectedAgentProfile?.models ?? []
    const selectedAvailability = capabilities.availability.values[agent]
    const agentAvailability = input.runAction
        ? Object.fromEntries(agentProfiles.map((profile) => [profile.name, { available: true, error: null }]))
        : capabilities.availability.values
    const selectedAgentAvailable = !!input.runAction
        || action.type !== 'agent'
        || (!!selectedAvailability?.available && !capabilities.availability.error)
    const backendAvailable = !!input.runAction || hasExecutionBackend()
    const executionDisabledMessage = !backendAvailable
        ? 'Action execution requires the Electron desktop app'
        : action.type === 'agent' && capabilities.availability.loading
            ? 'Checking agent executable availability'
            : action.type === 'agent' && !selectedAgentAvailable
                ? selectedAvailability?.error ?? capabilities.availability.error ?? `Agent executable is unavailable for ${agent}`
                : null
    const thinkingLevel = thinkingLevelOverride?.actionId === action.id ? thinkingLevelOverride.value : definitionThinkingLevel
    const conversationKey = promptContextKey
    const activePromptState: { key: string, status: PromptPreparationStatus, value: string } = promptState.key === promptKey
        ? promptState
        : {
            key: promptKey,
            status: action.type === 'agent' && !input.continueFrom && !sharedExecution ? 'loading' : 'ready',
            value: sharedPromptDraft || input.initialPrompt || '',
        }
    const prompt = activePromptState.value
    const promptPreparationPending = activePromptState.status === 'loading'
    const promptPreparationFailed = activePromptState.status === 'failed'
    const selectionKey = `${conversationKey}\u0000${input.continueFrom ?? ''}`
    const conversationHistory = conversationHistoryState.key === conversationKey ? conversationHistoryState.conversations : []
    const conversationHistoryLoading = !!input.enableConversations && conversationHistoryState.key !== conversationKey
    const selectedConversation = selectedConversationState.key === selectionKey ? selectedConversationState.conversation : null
    const selectedHistory = selectedConversation ? [...conversationHistory, selectedConversation] : conversationHistory
    const executionId = sharedExecution?.executionId ?? localExecutionId
    const runStatus = sharedExecution?.status ?? localRunStatus
    const runLogs = sharedExecution?.logs ?? localRunResult?.logs ?? []
    const sessionActive = runStatus === 'queued' || runStatus === 'running' || runStatus === 'waitingForInput'
    const agentActive = sessionActive && sharedExecution?.activeActionType === 'agent'
    const streamingActive = agentActive && !!sharedExecution?.activeActionStreaming
    const interactionReady = agentActive && !!sharedExecution?.interactionReady
    const manualFinishAvailable = streamingActive && !sharedExecution?.activeActionAutoFinish
    const showLiveConversation = !input.enableConversations
        ? !!sharedExecution
        : liveActionKey === conversationKey || runStatus === 'queued' || runStatus === 'running' || runStatus === 'waitingForInput'
    const sharedAgentTurn = showLiveConversation ? sharedExecution?.agentTurn ?? null : null
    const baseLiveConversation = sharedAgentTurn
        ? selectedHistory.find(({ id }) => id === sharedAgentTurn.conversationId) ?? null
        : null
    const liveConversation = sharedAgentTurn
        ? sharedExecution?.status !== 'running'
            && sharedExecution?.status !== 'waitingForInput'
            && baseLiveConversation?.status !== 'running'
            && baseLiveConversation?.status !== 'waitingForInput'
            ? baseLiveConversation
            : liveAgentConversation(sharedAgentTurn, action.id, context, sharedExecution?.status ?? 'running', baseLiveConversation)
        : null
    const displayedConversation = liveConversation ?? selectedConversation
    const conversations = mergeConversationHistory(selectedHistory, action.id, context, liveConversation)
    const continuationReference = liveConversation?.path
        ?? selectedConversation?.path
        ?? input.continueFrom
        ?? null
    const isFollowUp = action.type === 'agent'
        && (streamingActive || (runStatus !== 'queued' && runStatus !== 'running' && runStatus !== 'waitingForInput' && !!continuationReference))

    useEffect(() => {
        actionRef.current = action
        contextRef.current = context
    }, [action, context])

    useEffect(() => {
        const handlePromptDraftCleared = (event: Event) => {
            const detail = (event as CustomEvent<{ actionId: string, executionId: string }>).detail
            if (detail.executionId !== sharedExecution?.executionId) return
            if (detail.actionId !== sharedExecution.activeActionId) return

            setPromptState({ key: promptKey, status: 'ready', value: '' })
            setPromptResetToken((token) => token + 1)
        }
        actionExecutionService.addEventListener('promptDraftCleared', handlePromptDraftCleared)

        return () => actionExecutionService.removeEventListener('promptDraftCleared', handlePromptDraftCleared)
    }, [promptKey, sharedExecution?.activeActionId, sharedExecution?.executionId])

import { cleanup, fireEvent, render, screen } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { configService } from '../../services/config/config_service'
import { AppThemeProvider } from '../../theme/theme_provider'
import { AgentChatFab } from './agent_chat_fab'

describe('AgentChatFab', () => {
    beforeEach(() => {
        configService.init()
        window.md2Actions = {
            onActionExecution: vi.fn(() => vi.fn()),
            prepareActionPrompt: vi.fn(async () => ({ prompt: '' })),
        } as unknown as typeof window.md2Actions
        Object.defineProperty(window, 'innerHeight', { configurable: true, value: 800 })
        Object.defineProperty(window, 'innerWidth', { configurable: true, value: 1200 })
    })

    afterEach(() => {
        cleanup()
        delete window.md2Actions
        configService.clear()
    })

    it('opens and closes project-wide run form on plain clicks', async () => {
        render(<AgentChatFab />, { wrapper: AppThemeProvider })
        const button = screen.getByRole('button', { name: 'Project agent' })

        fireEvent.click(button)

        expect(screen.getByRole('dialog', { name: 'Run actions' })).toBeInTheDocument()
        expect(await screen.findByLabelText('Prompt')).toBeInTheDocument()
        expect(screen.getByRole('combobox', { name: 'Conversation history' })).toBeInTheDocument()
        expect(screen.getByLabelText('Conversation chat').compareDocumentPosition(screen.getByLabelText('Prompt')))
            .toBe(Node.DOCUMENT_POSITION_FOLLOWING)
        expect(document.querySelector('.MuiModal-root')).not.toBeInTheDocument()

        fireEvent.click(button)

        expect(screen.queryByRole('dialog', { name: 'Run actions' })).not.toBeInTheDocument()
    })

    it('moves without opening popup when pointer gesture crosses drag threshold', () => {
        render(<AgentChatFab />, { wrapper: AppThemeProvider })
        const button = screen.getByRole('button', { name: 'Project agent' })

        fireEvent.pointerDown(button, { clientX: 1140, clientY: 740, pointerId: 1 })
        fireEvent.pointerMove(button, { clientX: 900, clientY: 500, pointerId: 1 })
        fireEvent.pointerUp(button, { pointerId: 1 })
        fireEvent.click(button)

        expect(button).toHaveStyle({ left: '888px', top: '488px' })
        expect(screen.queryByRole('dialog', { name: 'Run actions' })).not.toBeInTheDocument()

        fireEvent.click(button)
        expect(screen.getByRole('dialog', { name: 'Run actions' })).toBeInTheDocument()
    })

    it('detaches the draggable popup while keeping its far corner fixed when resized from the top-left', () => {
        render(<AgentChatFab />, { wrapper: AppThemeProvider })
        const button = screen.getByRole('button', { name: 'Project agent' })
        fireEvent.click(button)
        const dialog = screen.getByRole('dialog', { name: 'Run actions' })
        const handle = screen.getByRole('separator', { name: 'Resize action popup from top-left' })
        dialog.getBoundingClientRect = vi.fn(() => new DOMRect(700, 200, 400, 450))

        fireEvent.pointerDown(handle, { clientX: 100, clientY: 100, pointerId: 1 })
        fireEvent.pointerMove(window, { clientX: 50, clientY: 40, pointerId: 1 })
        fireEvent.pointerUp(window, { pointerId: 1 })

        expect(button).toHaveStyle({ left: '1128px', top: '728px' })
        expect(dialog.style.width).toBe('450px')
        expect(dialog.style.height).toBe('510px')
        expect(dialog).toHaveStyle({ left: '650px', position: 'fixed', top: '140px' })
    })
})

