        vi.useFakeTimers()
        vi.setSystemTime(new Date('2026-01-01T00:00:05.000Z'))
    })

    afterEach(() => {
        cleanup()
        vi.useRealTimers()
    })

    it('freezes at the completed duration when the run is done', () => {
        render(
            <ConversationTimer completedAt="2026-01-01T00:01:30.000Z" startedAt="2026-01-01T00:00:00.000Z" />,
        )

